import http from 'k6/http';
import { check, fail, sleep } from 'k6';
import execution from 'k6/execution';
import { Rate, Trend } from 'k6/metrics';

const BASE_URL = (__ENV.CRM_STABILITY_BASE_URL || 'http://127.0.0.1:3001').replace(/\/$/, '');
const USERNAME = __ENV.CRM_STABILITY_USERNAME;
const PASSWORD = __ENV.CRM_STABILITY_PASSWORD;
const MARKER = __ENV.CRM_STABILITY_MARKER;
const SUMMARY_PATH = __ENV.CRM_STABILITY_SUMMARY_PATH;
const READ_VUS = Number.parseInt(__ENV.CRM_STABILITY_READ_VUS || '8', 10);
const READ_DURATION = __ENV.CRM_STABILITY_DURATION || '3m';
const WRITE_ITERATIONS = Number.parseInt(__ENV.CRM_STABILITY_WRITE_ITERATIONS || '8', 10);

const crmErrors = new Rate('crm_errors');
const customerWriteDuration = new Trend('customer_write_duration', true);
let sessionReady = false;

if (!USERNAME || !PASSWORD || !MARKER || !SUMMARY_PATH) {
  throw new Error('缺少 CRM stability 测试环境变量');
}

export const options = {
  scenarios: {
    steady_reads: {
      executor: 'constant-vus',
      exec: 'readFlow',
      vus: READ_VUS,
      duration: READ_DURATION,
      gracefulStop: '15s',
    },
    controlled_writes: {
      executor: 'shared-iterations',
      exec: 'writeFlow',
      vus: Math.min(2, WRITE_ITERATIONS),
      iterations: WRITE_ITERATIONS,
      maxDuration: '2m',
      startTime: '10s',
    },
  },
  thresholds: {
    checks: ['rate>0.99'],
    crm_errors: ['rate<0.01'],
    http_req_failed: ['rate<0.01'],
    'http_req_duration{scenario:steady_reads}': ['p(95)<1500', 'p(99)<3000'],
    customer_write_duration: ['p(95)<2000'],
  },
  summaryTrendStats: ['avg', 'med', 'p(90)', 'p(95)', 'p(99)', 'max'],
  noCookiesReset: true,
};

function ensureSession() {
  if (sessionReady) return;
  const csrf = http.get(`${BASE_URL}/api/auth/csrf`, { tags: { endpoint: 'auth_csrf' } });
  const csrfOk = check(csrf, {
    'csrf status 200': (response) => response.status === 200,
    'csrf token present': (response) => Boolean(response.json('csrfToken')),
  });
  if (!csrfOk) {
    crmErrors.add(1);
    fail(`CSRF 请求失败，HTTP ${csrf.status}`);
  }

  const login = http.post(
    `${BASE_URL}/api/auth/callback/credentials`,
    {
      csrfToken: csrf.json('csrfToken'),
      username: USERNAME,
      password: PASSWORD,
      redirect: 'false',
      callbackUrl: `${BASE_URL}/`,
    },
    { redirects: 0, tags: { endpoint: 'auth_login' } },
  );
  const loginOk = check(login, {
    'login redirects after success': (response) => [200, 302, 303].includes(response.status),
  });
  const session = http.get(`${BASE_URL}/api/auth/session`, { tags: { endpoint: 'auth_session' } });
  const sessionOk = check(session, {
    'session status 200': (response) => response.status === 200,
    'session user present': (response) => Boolean(response.json('user.id')),
  });
  if (!loginOk || !sessionOk) {
    crmErrors.add(1);
    fail(`登录会话建立失败，login=${login.status}, session=${session.status}`);
  }
  sessionReady = true;
}

function checked(response, label, requireRequestId = false) {
  const assertions = {
    [`${label} status 200`]: (value) => value.status === 200,
  };
  if (requireRequestId) {
    assertions[`${label} request id`] = (value) => Boolean(value.headers['X-Request-Id']);
  }
  const ok = check(response, assertions);
  crmErrors.add(!ok);
  return ok;
}

export function readFlow() {
  ensureSession();
  const health = http.get(`${BASE_URL}/api/health`, { tags: { endpoint: 'health' } });
  checked(health, 'health');

  const responses = http.batch([
    ['GET', `${BASE_URL}/api/customers?page=1&pageSize=20`, null, { tags: { endpoint: 'customers' } }],
    ['GET', `${BASE_URL}/api/customers?page=1&pageSize=20&keyword=${encodeURIComponent(MARKER)}`, null, { tags: { endpoint: 'customer_search' } }],
    ['GET', `${BASE_URL}/api/statistics/sales-overview`, null, { tags: { endpoint: 'sales_overview' } }],
    ['GET', `${BASE_URL}/api/statistics/funnel`, null, { tags: { endpoint: 'sales_funnel' } }],
    ['GET', `${BASE_URL}/api/reminders`, null, { tags: { endpoint: 'reminders' } }],
  ]);
  checked(responses[0], 'customers');
  checked(responses[1], 'customer search');
  checked(responses[2], 'sales overview');
  checked(responses[3], 'sales funnel');
  checked(responses[4], 'reminders');
  sleep(1);
}

export function writeFlow() {
  ensureSession();
  const iteration = execution.scenario.iterationInTest;
  const digits = MARKER.replace(/\D/g, '').slice(-14);
  const requestId = `${MARKER}-${iteration}`;
  const payload = JSON.stringify({
    name: `${MARKER}-${iteration}`,
    company: 'CRM stability test',
    phone: `9${digits}${String(iteration).padStart(4, '0')}`.slice(0, 20),
    source: 'OTHER',
    notes: 'test profile controlled write',
  });
  const response = http.post(`${BASE_URL}/api/customers`, payload, {
    headers: { 'Content-Type': 'application/json', 'x-request-id': requestId },
    tags: { endpoint: 'customer_create' },
  });
  customerWriteDuration.add(response.timings.duration);
  checked(response, 'customer create', true);
}

export function handleSummary(data) {
  const duration = data.metrics.http_req_duration?.values || {};
  const failed = data.metrics.http_req_failed?.values || {};
  const checks = data.metrics.checks?.values || {};
  return {
    [SUMMARY_PATH]: JSON.stringify(data, null, 2),
    stdout: `k6 summary: p95=${duration['p(95)']}ms p99=${duration['p(99)']}ms failed=${failed.rate} checks=${checks.rate}\n`,
  };
}
